#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int maxSubarrayLength(vector<int>& nums) {
        vector<int> st;
        for(int i=0;i<(int)nums.size();++i) {
            if(st.empty()||nums[i]>nums[st.back()])st.push_back(i);
        }
        int ans=0;
        for(int j=(int)nums.size()-1;j>=0;--j) {
            while(!st.empty()&&nums[st.back()]>nums[j]) {
                ans=max(ans,j-st.back()+1);st.pop_back();
            }
        }
        return ans;
    }
};
